using UnityEngine;
using UnityEngine.AI;
using System.Collections.Generic;

/// <summary>
/// One cell of the colony's perimeter. Walls carve the NavMesh, so they genuinely block
/// pathing rather than merely being attackable, and enemies must break through.
/// </summary>
/// <remarks>
/// A wall registers its grid cell with WallGrid, which gives every other system an O(1)
/// answer to "is there a wall here" - that is how gate conversion and the wall-under-attack
/// scan avoid raycasting. Its visible mesh is generated by WallConnector from the
/// occupancy of its neighbours, so a wall's shape depends on the cells around it.
///
/// The carve is the expensive part (2026-09-28, the wall lag): every carve appearing,
/// vanishing or MOVING rebuilds its NavMesh tile. So a wall never moves once its obstacle
/// exists (a finishing site spawns it on its snapped spot, see ConstructionSite.Complete),
/// its box is the same one the site carved, and it carves immediately rather than after a
/// "stationary" timer - it is never going to move.
/// </remarks>
public class Wall : MonoBehaviour, ITargetable, IBuildingIdentity
{
    public BuildingType BuildingType => isStoneWall ? BuildingType.StoneWall : BuildingType.WoodenWall;

    // Owner (lap step 1 commit 5). Set by Spawn.Owned right after Instantiate
    // (commit 6); the player's when nothing set it. Read in Start or later, never Awake.
    Faction owner;
    public Faction Faction { get => owner ?? (owner = Factions.Player); set => owner = value; }
    [Header("Wall Type")]
    public bool isStoneWall = false;  // false = wooden wall, true = stone wall

    [Header("Health")]
    public float maxHealth = 150f;  // Wooden=150, Stone=300
    private Health healthComponent;
    public Health CachedHealth => healthComponent;

    [Header("Building Placement")]
    public float noBuildRadius = 0f;  // Walls have no no-build zone - they can be placed adjacent

    /// <summary>
    /// The carve box of a wall cell, and of a wall site: slightly smaller than the 1 m cell
    /// so a gate between two walls leaves a walkable gap. A site uses the same box at the
    /// same world height, so the hand-over from site to wall changes nothing on the mesh.
    /// </summary>
    public static readonly Vector3 CarveSize = new Vector3(0.9f, 2f, 0.9f);
    /// <summary>Height of the carve box's centre above a wall's pivot.</summary>
    public const float CarveCentreY = 1f;

    private Vector2Int gridPos;
    private bool registered = false;
    private NavMeshObstacle obstacle;
    private bool carveCounted;    // PerfCounters: this wall's carve appearing, once
    private bool carveReleased;   // ... and vanishing, once (death, conversion or destroy)

    // Static event fired when ANY wall is destroyed — enemies subscribe for breach detection
    public static event System.Action OnAnyWallDestroyed;

    public static IReadOnlyList<Wall> ActiveList => ActiveRegistry<Wall>.List;

    void Awake() { ActiveRegistry<Wall>.Register(this); }

    void Start()
    {
        // Shape and position first, so the renderers the fog and the cutout collect are
        // the final ones and nothing moves after the carve exists.
        WallConnector connector = GetComponent<WallConnector>();
        if (connector != null) connector.EnsureInitialized();

        // A wall hides a unit's legs from the tilted RTS camera, so it opens a window
        // for any unit behind it like every other occluder (2026-09-08). The old fade
        // excluded walls because a line of ghosting cells read worse than the problem; a
        // cutout has no such cost.
        OccluderCutout.AttachTo(gameObject);
        // Another colony's wall is shown only on watched ground, like its huts (2026-09-28:
        // rival walls drew through the fog).
        if (!Faction.IsPlayer) FogVisibility.Attach(gameObject, FogVisibility.Rule.Visible);

        // Setup Health component
        healthComponent = GetComponent<Health>();
        if (healthComponent == null)
        {
            healthComponent = gameObject.AddComponent<Health>();
        }
        healthComponent.maxHealth = maxHealth;
        healthComponent.currentHealth = maxHealth;
        healthComponent.destroyOnDeath = true;
        healthComponent.destroyDelay = 0.5f;
        healthComponent.showHealthText = true;
        healthComponent.showObjectName = true;
        healthComponent.hideWhenFull = true;
        healthComponent.onDeath.AddListener(OnWallDestroyed);

        // CRITICAL: carve the NavMesh so walls block enemy pathfinding. Usually already
        // done by the site that finished into this wall, in which case nothing changes.
        ClaimCarveAndCell();
    }

    /// <summary>
    /// Configure this wall's carve and claim its grid cell, now. Idempotent. Called by
    /// Start and, earlier, by the finishing site the frame it spawns the wall, so the
    /// wall's carve and cell replace the site's in one frame with no gap.
    /// </summary>
    public void ClaimCarveAndCell()
    {
        if (obstacle == null) obstacle = GetComponent<NavMeshObstacle>();
        if (obstacle != null && !carveReleased)
        {
            ConfigureCarve(obstacle, CarveCentreY);
            if (!carveCounted) { carveCounted = true; PerfCounters.Hit(PerfCounters.K.CarveChange); }
        }

        if (!registered && WallGrid.Instance != null)
        {
            gridPos = WallGrid.Instance.WorldToGrid(transform.position);
            WallGrid.Instance.Register(gridPos, this);
            registered = true;
        }
    }

    /// <summary>
    /// The one carve setup for a wall cell and a wall site. Every property is written only
    /// when it differs, because a changed obstacle is a re-carved tile.
    /// <paramref name="centreY"/> is the box centre above the obstacle's pivot.
    /// </summary>
    public static void ConfigureCarve(NavMeshObstacle o, float centreY)
    {
        Vector3 centre = new Vector3(0f, centreY, 0f);
        if (o.shape != NavMeshObstacleShape.Box) o.shape = NavMeshObstacleShape.Box;
        if (o.size != CarveSize) o.size = CarveSize;
        if (o.center != centre) o.center = centre;
        if (!o.carving) o.carving = true;
        // A wall never moves, so there is nothing to wait for: carve at once rather than
        // after a "stationary" timer, which only left a gap in the mesh at every hand-over.
        if (o.carveOnlyStationary) o.carveOnlyStationary = false;
        if (!o.enabled) o.enabled = true;
    }

    void OnWallDestroyed()
    {
        UnregisterFromGrid();

        // Immediately release the NavMesh carve and disable colliders so stacked
        // enemies can path through the breach during the 0.5s fade-out instead of
        // being wedged against the corpse. Fixes retarget freeze on wall death.
        ReleaseCarve();
        Collider[] cols = GetComponentsInChildren<Collider>();
        for (int i = 0; i < cols.Length; i++) cols[i].enabled = false;

        // Notify all enemies that a wall was destroyed (breach detection)
        OnAnyWallDestroyed?.Invoke();
    }

    void OnDestroy()
    {
        ActiveRegistry<Wall>.Unregister(this);
        UnregisterFromGrid();
        if (carveCounted && !carveReleased)
        {
            carveReleased = true;
            PerfCounters.Hit(PerfCounters.K.CarveChange);   // the component goes with the object
        }
    }

    private void ReleaseCarve()
    {
        if (carveReleased) return;
        carveReleased = true;
        if (obstacle == null) obstacle = GetComponent<NavMeshObstacle>();
        if (obstacle != null && obstacle.enabled)
        {
            obstacle.enabled = false;
            PerfCounters.Hit(PerfCounters.K.CarveChange);
        }
    }

    private void UnregisterFromGrid()
    {
        if (registered && WallGrid.Instance != null)
        {
            WallGrid.Instance.Unregister(gridPos, this);
            registered = false;
        }
    }

    // ------------------------------------------------------------------
    // Gate conversion (2026-09-28: gates are up to three cells wide)
    // ------------------------------------------------------------------

    // The walls a conversion takes, reused so a G press allocates no list.
    private static readonly Wall[] spanWalls = new Wall[Gate.MaxWidth];

    /// <summary>
    /// Convert this wall and up to two neighbours in the same straight run into ONE gate
    /// (G key, and the governor's GateOpenings - the single owner of the conversion). The
    /// gate's transform is on the middle cell; a run too short for three makes it as wide
    /// as fits. The caller has already refused a slanted wall and charged the cost.
    /// Returns the gate (its <see cref="Gate.Width"/> says how wide it came out).
    /// </summary>
    /// <remarks>
    /// A neighbour joins only when it is a finished, living wall of the same owner and
    /// material, with no slanted link and nothing touching it from the side - a corner or
    /// T in the doorway would leave a wall arm pointing into the opening. The axis with the
    /// wider run wins; a tie goes to the axis this wall already links along.
    /// The gate claims every cell in this same frame, before the walls are gone, so the
    /// opening is never empty in the grid (the governor gates a ring opening cell by cell
    /// in one call and would otherwise order a new wall site into the gap).
    /// </remarks>
    public Gate UpgradeToGate()
    {
        WallGrid grid = WallGrid.Instance;
        Vector2Int cell = grid.WorldToGrid(transform.position);

        int xLo, xHi, zLo, zHi;
        PlanSpan(grid, cell, true, out xLo, out xHi);
        PlanSpan(grid, cell, false, out zLo, out zHi);
        int xWidth = xHi - xLo + 1, zWidth = zHi - zLo + 1;
        bool alongX;
        if (xWidth != zWidth) alongX = xWidth > zWidth;
        else
        {
            int mask = grid.GetNeighborMask(cell);
            bool linksZ = (mask & (WallGrid.NORTH | WallGrid.SOUTH)) != 0;
            bool linksX = (mask & (WallGrid.EAST | WallGrid.WEST)) != 0;
            alongX = linksX || !linksZ;
        }
        int lo = alongX ? xLo : zLo, hi = alongX ? xHi : zHi;

        // An odd width sits on its middle cell; a two-wide gate stays on this one.
        int mid = (hi - lo) % 2 == 0 ? (lo + hi) / 2 : 0;
        Vector2Int step = alongX ? new Vector2Int(1, 0) : new Vector2Int(0, 1);
        Vector2Int anchor = cell + step * mid;
        lo -= mid;
        hi -= mid;

        // Take the walls: their HP carries over as a fraction, their carves go now.
        bool stone = isStoneWall;
        float current = 0f, max = 0f;
        int count = 0;
        for (int k = lo; k <= hi; k++)
        {
            Wall w = k + mid == 0 ? this : grid.GetWallAt(anchor + step * k) as Wall;
            if (w == null) continue;
            Health h = w.healthComponent;
            current += h != null ? h.currentHealth : w.maxHealth;
            max += h != null ? h.maxHealth : w.maxHealth;
            w.UnregisterFromGrid();
            w.ReleaseCarve();
            spanWalls[count++] = w;
        }
        float healthRatio = max > 0f ? Mathf.Clamp01(current / max) : 1f;

        // Create the gate on the middle cell, standing where a wall there would stand
        GameObject gateObj = new GameObject(stone ? "StoneGate" : "WoodenGate");
        gateObj.transform.SetPositionAndRotation(WallConnector.SnapToCell(grid.GridToWorld(anchor)), Quaternion.identity);
        gateObj.layer = gameObject.layer;

        Gate gate = gateObj.AddComponent<Gate>();
        gate.Faction = Faction;   // the wall's owner, or a rival's gate is the player's (overnight 2026-09-17)
        gate.isStoneGate = stone;
        gate.maxHealth = Gate.CellHealth(stone) * (hi - lo + 1);
        gate.SetSpan(anchor, alongX, lo, hi);

        // NOTE: Gates do NOT have NavMeshObstacle - friendlies walk through freely
        // Enemies are caught by Gate's trigger collider and forced to attack

        // The wall's own material (2026-09-28; was a new Sprites/Default material per gate,
        // unfogged and never freed). A stock URP Lit asset, so the gate's OccluderCutout
        // swaps it onto the cutout + fog shader like any wall.
        gateObj.AddComponent<MeshFilter>();
        MeshRenderer mr = gateObj.AddComponent<MeshRenderer>();
        mr.sharedMaterial = StockMaterial(stone);
        gateObj.AddComponent<WallConnector>();

        gate.ClaimCells();

        // Set health proportionally after Gate.Start() runs (defer with a frame delay)
        // Gate.Start() initializes health, so we need to apply ratio after
        gate.StartCoroutine(ApplyHealthRatioNextFrame(gateObj, healthRatio));

        // Destroy the walls it replaced
        for (int i = 0; i < count; i++)
        {
            Destroy(spanWalls[i].gameObject);
            spanWalls[i] = null;
        }
        return gate;
    }

    /// <summary>
    /// How far a gate on <paramref name="cell"/> can reach along one axis: lo..hi around
    /// it, at most <see cref="Gate.MaxWidth"/> cells, centred when both sides allow.
    /// </summary>
    private void PlanSpan(WallGrid grid, Vector2Int cell, bool alongX, out int lo, out int hi)
    {
        Vector2Int step = alongX ? new Vector2Int(1, 0) : new Vector2Int(0, 1);
        Vector2Int side = alongX ? new Vector2Int(0, 1) : new Vector2Int(1, 0);
        int reach = Gate.MaxWidth - 1;

        int pos = 0, neg = 0;
        while (pos < reach && CanJoinGate(grid, cell + step * (pos + 1), side)) pos++;
        while (neg < reach && CanJoinGate(grid, cell - step * (neg + 1), side)) neg++;

        if (neg >= 1 && pos >= 1) { lo = -1; hi = 1; }         // centred on this wall
        else if (pos >= 2) { lo = 0; hi = 2; }
        else if (neg >= 2) { lo = -2; hi = 0; }
        else { lo = -neg; hi = pos; }                          // as wide as fits
    }

    private bool CanJoinGate(WallGrid grid, Vector2Int c, Vector2Int side)
    {
        Wall w = grid.GetWallAt(c) as Wall;
        if (w == null || w.isStoneWall != isStoneWall || w.Faction != Faction) return false;
        if (w.healthComponent != null && !w.healthComponent.IsAlive) return false;
        if (grid.HasWallAt(c + side) || grid.HasWallAt(c - side)) return false;
        return !grid.HasDiagonalLink(c);
    }

    /// <summary>The wall prefab's own material asset (never an instance), or this wall's as a fallback.</summary>
    private Material StockMaterial(bool stone)
    {
        BuildingData data = BuildingDatabase.Instance != null
            ? BuildingDatabase.Instance.GetBuildingData(stone ? BuildingType.StoneWall : BuildingType.WoodenWall) : null;
        if (data != null && data.finishedBuildingPrefab != null)
        {
            MeshRenderer prefabRenderer = data.finishedBuildingPrefab.GetComponent<MeshRenderer>();
            if (prefabRenderer != null && prefabRenderer.sharedMaterial != null) return prefabRenderer.sharedMaterial;
        }
        MeshRenderer own = GetComponent<MeshRenderer>();
        return own != null ? own.sharedMaterial : null;
    }

    private static System.Collections.IEnumerator ApplyHealthRatioNextFrame(GameObject gateObj, float ratio)
    {
        yield return null; // Wait one frame for Start() to run
        if (gateObj != null)
        {
            Health h = gateObj.GetComponent<Health>();
            if (h != null)
            {
                h.currentHealth = h.maxHealth * ratio;
            }
        }
    }

    // Visual feedback in Scene view
    void OnDrawGizmosSelected()
    {
        // Draw no-build radius
        Gizmos.color = new Color(0.5f, 0.5f, 1f, 0.3f);
        Gizmos.DrawWireSphere(transform.position, noBuildRadius);
    }
}
